            entity.setEncounterId( command.getEncounterId() );
            entity.setEncounterNumber( command.getEncounterNumber() );
            entity.setStartDateTime( command.getStartDateTime() );
            entity.setEndDateTime( command.getEndDateTime() );
            entity.setPatient( command.getPatient() );
            entity.setClinician( command.getClinician() );
            entity.setFacility( command.getFacility() );
            entity.setAppointment( command.getAppointment() );
            entity.setDiagnoses( command.getDiagnoses() );
            entity.setProcedures( command.getProcedures() );
            entity.setObservations( command.getObservations() );
            entity.setOrders( command.getOrders() );
