	/**
	 * Method to retrieve the Encounter via EncounterFetchOneSummary
	 * @param 	summary EncounterFetchOneSummary
	 * @return 	EncounterFetchOneResponse
	 */
	public Encounter getEncounter( EncounterFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "EncounterFetchOneSummary arg cannot be null" );

		Encounter entity = null;
		UUID id = summary.getEncounterId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Encounter using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Encounters
	 *
	 * @return 	List<Encounter>
	 */
    public List<Encounter> getAllEncounter() {
		List<Encounter> list = projector.findAll( new FindAllEncounterQuery() );
		return list;
	}

